def extract_dates(text):
    """Extract dates from text in Indian formats (DD/MM/YYYY, DD-Mon-YYYY, AY 20XX-YY, etc.)."""
    dates = []
    
    # 1. Assessment / Financial Year: e.g. AY 2024-25 or FY 2023-24
    ay_match = re.search(r"\b(AY|FY)\s*[-:]?\s*(20\d{2}[-–]\d{2,4})\b", text, re.IGNORECASE)
    if ay_match:
        dates.append(f"{ay_match.group(1).upper()}_{ay_match.group(2).replace('–', '-')}")
        
    # 2. Written ordinal date: e.g. 1st day of October 2024, 15th August 2024
    ord_match = re.search(
        r"\b(\d{1,2})(?:st|nd|rd|th)?\s+(?:day\s+of\s+)?(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(20\d{2}|19\d{2})\b",
        text, re.IGNORECASE
    )
    if ord_match:
        d, m, y = ord_match.groups()
        months = {'jan':1,'feb':2,'mar':3,'apr':4,'may':5,'jun':6,'jul':7,'aug':8,'sep':9,'oct':10,'nov':11,'dec':12}
        m_num = months.get(m[:3].lower(), 1)
        dates.append(f"{y}-{m_num:02d}-{int(d):02d}")
        
    # 3. Standard DD/MM/YYYY or DD-MM-YYYY
    std_dates = re.findall(r"\b(\d{1,2})[/.-](\d{1,2})[/.-](20\d{2}|19\d{2})\b", text)
    for d, m, y in std_dates[:3]:
        dates.append(f"{y}-{int(m):02d}-{int(d):02d}")
        
    # 4. Month Year: e.g. Oct 2024, October 2024
    month_year = re.findall(r"\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(20\d{2})\b", text, re.IGNORECASE)
    for m, y in month_year[:2]:
        dates.append(f"{m[:3].capitalize()}_{y}")
        
    return dates

def deduce_category(text, original_name="", return_details=False):
    """Categorize document based strictly on content metadata text (filename is NEVER evaluated).
    When multiple categories match, the category with the maximum number of matched identifiers wins."""
    content = (text or "").strip()
    if not content:
        if return_details:
            return "Other Document", 0, {"keywords": [], "patterns": [], "identifiers": [], "matched_count": 0}
        return "Other Document", 0
        
    lower_text = content.lower()
    normalized = re.sub(r"[\W_]+", " ", lower_text)
    scores = {}
    evidence_breakdown = {}
    
    for category, rule in TAXONOMY_RULES.items():
        matched_identifiers = []
        for kw in rule.get("keywords", []):
            if kw in lower_text or kw in normalized:
                matched_identifiers.append(kw)
        for pattern in rule.get("regex", []):
            if re.search(pattern, content, re.IGNORECASE) or re.search(pattern, normalized, re.IGNORECASE):
                matched_identifiers.append(pattern)
                
        if matched_identifiers:
            matched_count = len(matched_identifiers)
            total_specificity = sum(len(m) for m in matched_identifiers)
            scores[category] = (matched_count, total_specificity, rule.get("weight", 3))
            evidence_breakdown[category] = {
                "keywords": [k for k in matched_identifiers if not k.startswith("\\b") and not k.startswith("r\"")],
                "patterns": [p for p in matched_identifiers if p.startswith("\\b") or p.startswith("r\"")],
                "identifiers": matched_identifiers,
                "matched_count": matched_count,
                "score": matched_count
            }
            
    if not scores:
        if return_details:
            return "Other Document", 0, {"keywords": [], "patterns": [], "identifiers": [], "matched_count": 0}
        return "Other Document", 0
        
    # The category with the MAXIMUM number of matched identifiers wins
    best_category = max(scores.items(), key=lambda x: (x[1][0], x[1][2], x[1][1]))
    details = evidence_breakdown.get(best_category[0], {"keywords": [], "patterns": [], "identifiers": [], "score": best_category[1][0]})
    
    if return_details:
        return best_category[0], best_category[1][0], details
    return best_category[0], best_category[1][0]

CATEGORY_CODES = {
    'Identity': 'IDN',
    'Education': 'EDU',
    'Medical': 'MED',
    'Finance': 'FIN',
    'Work': 'WRK',
    'Property': 'PRO',
    'Business': 'BIZ',
    'Legal': 'LAW',
    'Transport': 'TPT',
    'Travel': 'TRV',
    'Insurance': 'INS',
    'Utilities': 'UTL',
    'Agriculture': 'AGR'
}

def resolve_category_code(category: str) -> str:
    if not category:
        return 'OTH'
    c_clean = str(category).strip()
    if c_clean in CATEGORY_CODES:
        return CATEGORY_CODES[c_clean]
    for cat, code in CATEGORY_CODES.items():
        if cat.lower() == c_clean.lower():
            return code
    low = c_clean.lower()
    if any(k in low for k in ['ident', 'aadhaar', 'pan', 'passport', 'voter', 'permanent account', 'ration', 'citizenship']):
        return 'IDN'
    if any(k in low for k in ['educat', 'marksheet', 'degree', 'school', 'college', 'transcript', 'diploma']):
        return 'EDU'
    if any(k in low for k in ['medic', 'health', 'hosp', 'doctor', 'patient', 'lab', 'patholog', 'prescription', 'diagnostic']):
        return 'MED'
    if any(k in low for k in ['finan', 'bank', 'tax', 'income', 'salary', 'loan', 'invest', 'saving', 'account', 'statement', 'passbook', 'credit', 'debit', 'cheque', 'demat', 'mutual fund', 'form 16', 'form 26as', 'itr']):
        return 'FIN'
    if any(k in low for k in ['work', 'employ', 'job', 'offer', 'reliev', 'apprais', 'provident', 'epf', 'pf', 'gratuity', 'pension', 'wage']):
        return 'WRK'
    if any(k in low for k in ['prop', 'land', 'rent', 'lease', 'deed', 'flat', 'house', 'building', 'khatauni', 'khasra', 'mutation', 'patta']):
        return 'PRO'
    if any(k in low for k in ['busin', 'gst', 'trade', 'tender', 'incorporat', 'comp', 'msme', 'udyam']):
        return 'BIZ'
    if any(k in low for k in ['law', 'legal', 'court', 'affidavit', 'notar', 'notice', 'agreement', 'contract']):
        return 'LAW'
    if any(k in low for k in ['transport', 'vehic', 'rc', 'driving', 'toll', 'permit', 'fastag', 'challan']):
        return 'TPT'
    if any(k in low for k in ['travel', 'ticket', 'flight', 'train', 'boarding', 'visa', 'hotel']):
        return 'TRV'
    if any(k in low for k in ['insur', 'policy', 'claim', 'premium']):
        return 'INS'
    if any(k in low for k in ['utilit', 'bill', 'electric', 'water', 'gas', 'broadband', 'telecom', 'phone']):
        return 'UTL'
    if any(k in low for k in ['agri', 'kisan', 'crop', 'soil']):
        return 'AGR'
    return 'OTH'

MONTH_NAMES = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
MONTH_LOOKUP = {
    'jan': 0, 'january': 0, 'feb': 1, 'february': 1, 'mar': 2, 'march': 2,
    'apr': 3, 'april': 3, 'may': 4, 'jun': 5, 'june': 5, 'jul': 6, 'july': 6,
    'aug': 7, 'august': 7, 'sep': 8, 'sept': 8, 'september': 8, 'oct': 9, 'october': 9,
    'nov': 10, 'november': 10, 'dec': 11, 'december': 11
}

def format_dd_mmm_yy(raw_date: str) -> str:
    if raw_date:
        s = str(raw_date).strip()
        # 1. YYYY-MM-DD
        m = re.search(r'\b(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})\b', s)
        if m:
            y = int(m.group(1)) % 100
            mo = int(m.group(2)) - 1
            d = int(m.group(3))
            if 0 <= mo <= 11 and 1 <= d <= 31:
                return f"{d:02d}{MONTH_NAMES[mo]}{y:02d}"

        # 2. DD-MM-YYYY or DD/MM/YY
        m = re.search(r'\b(\d{1,2})[-/.](\d{1,2})[-/.](20\d{2}|\d{2})\b', s)
        if m:
            d = int(m.group(1))
            mo = int(m.group(2)) - 1
            y = int(m.group(3))
            if y > 1900:
                y %= 100
            if 0 <= mo <= 11 and 1 <= d <= 31:
                return f"{d:02d}{MONTH_NAMES[mo]}{y:02d}"

        # 3. DD-Mon-YYYY or DD Mon YYYY or DDMonYY
        m = re.search(r'\b(\d{1,2})[-/\s]*([a-zA-Z]{3,})[-/\s]*(20\d{2}|\d{2})\b', s)
        if m:
            d = int(m.group(1))
            m_str = m.group(2).lower()
            y = int(m.group(3))
            if y > 1900:
                y %= 100
            mo = MONTH_LOOKUP.get(m_str) or MONTH_LOOKUP.get(m_str[:3])
            if mo is not None and 1 <= d <= 31:
                return f"{d:02d}{MONTH_NAMES[mo]}{y:02d}"

        # 4. Mon DD, YYYY
        m = re.search(r'\b([a-zA-Z]{3,})[-/\s]+(\d{1,2})[-/\s,\'"]+(20\d{2}|\d{2})\b', s)
        if m:
            m_str = m.group(1).lower()
            d = int(m.group(2))
            y = int(m.group(3))
            if y > 1900:
                y %= 100
            mo = MONTH_LOOKUP.get(m_str) or MONTH_LOOKUP.get(m_str[:3])
            if mo is not None and 1 <= d <= 31:
                return f"{d:02d}{MONTH_NAMES[mo]}{y:02d}"

    now = datetime.now()
    d = now.day
    mo = now.month - 1
    y = now.year % 100
    return f"{d:02d}{MONTH_NAMES[mo]}{y:02d}"

