def abbreviate_doc_type(doc_type: str, max_len: int = 24) -> str:
    if not doc_type or not str(doc_type).strip():
        return 'Document'[:max_len]
    clean = str(doc_type).strip()
    lower = clean.lower()
    if lower in PHRASE_ABBREVIATIONS:
        return PHRASE_ABBREVIATIONS[lower][:max_len]

    words = [w for w in re.split(r'[\s_\-]+', clean) if w]
    pascal_parts = []
    for w in words:
        w_low = w.lower()
        if w_low in WORD_ABBREVIATIONS:
            pascal_parts.append(WORD_ABBREVIATIONS[w_low])
        else:
            cleaned = re.sub(r'[^a-zA-Z0-9]', '', w)
            if cleaned:
                pascal_parts.append(cleaned[0].upper() + cleaned[1:])
    result = "".join(pascal_parts) or 'Document'
    return result[:max_len]

def generate_compliant_proposed_name(category: str, document_type: str = '', issued_date: str = '', original_name: str = '', text: str = '') -> str:
    cat_code = resolve_category_code(category)
    date_val = issued_date
    if not date_val:
        extracted = extract_dates(f"{text} {original_name}")
        date_val = extracted[0] if extracted else ''
    date_formatted = format_dd_mmm_yy(date_val)

    ext = '.pdf'
    if original_name and '.' in original_name:
        raw_ext = '.' + original_name.rsplit('.', 1)[-1].lower()
        if 2 <= len(raw_ext) <= 6:
            ext = raw_ext

    max_doc_len = max(4, 40 - 3 - 1 - 1 - 7 - len(ext))
    effective_type = document_type or category
    abbrev = abbreviate_doc_type(effective_type, max_doc_len)

    filename = f"{cat_code}_{abbrev}_{date_formatted}{ext}"
    if len(filename) > 40:
        excess = len(filename) - 40
        truncated_abbrev = abbrev[:max(1, len(abbrev) - excess)]
        return f"{cat_code}_{truncated_abbrev}_{date_formatted}{ext}"
    return filename

def is_compliant_proposed_name(name: str) -> bool:
    """Check if filename strictly follows the Android <= 40-char naming convention:
    CAT_DocumentNameAbbrev_ddMMMyy.ext
    """
    if not name or not isinstance(name, str) or len(name) > 40 or name in ('N/A', '...'):
        return False
    return bool(re.match(r'^[A-Z]{3}_[A-Za-z0-9]+_[0-9]{2}[A-Za-z]{3}[0-9]{2}\.[a-zA-Z0-9]+$', name))

def generate_proposed_name(category, text="", original_name="", document_type="", issued_date=""):
    """Generate a compliant <= 40 char proposed name strictly consistent with Android app:
    CAT_DocumentNameAbbrev_ddMMMyy.ext
    """
    return generate_compliant_proposed_name(
        category=category,
        document_type=document_type,
        issued_date=issued_date,
        original_name=original_name,
        text=text
    )

def classify_and_name_locally(text, original_name="", return_details=False):
    """Run local Indian document rules on text to return category, proposed name, and structured evidence."""
    cat, score, details = deduce_category(text, original_name, return_details=True)
    proposed = generate_proposed_name(cat, text, original_name)
    
    matched_kws = details.get("keywords", [])
    matched_pats = details.get("patterns", [])
    
    basis_parts = []
    if matched_kws:
        clean_kws = ", ".join(matched_kws[:6])
        basis_parts.append(f"Matched Keywords: [{clean_kws}]")
    if matched_pats:
        basis_parts.append(f"Triggered Patterns: {len(matched_pats)} regex rule(s)")
    if score > 0:
        basis_parts.append(f"Confidence Weight: {score}")
    else:
        basis_parts.append("Basis: General document fallback (no specific taxonomy patterns matched)")
        
    dates = extract_dates(f"{text} {original_name}")
    if dates:
        basis_parts.append(f"Extracted Date: {dates[0]}")
        
    if re.search(r"\b(draft|incomplete)\b", f"{text} {original_name}", re.IGNORECASE):
        basis_parts.append("Status: Incomplete / Draft Document Detected")
        
    evidence_summary = " • " + " | ".join(basis_parts)
    
    if return_details:
        return cat, proposed, evidence_summary
    return cat, proposed
